import{_ as t,o as s,c as a,ao as o}from"./chunks/framework.ucUddl5u.js";const u=JSON.parse('{"title":"Quickstart","description":"","frontmatter":{},"headers":[],"relativePath":"start/quickstart.md","filePath":"start/quickstart.md","lastUpdated":null}'),n={name:"start/quickstart.md"};function i(r,e,l,h,d,c){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="Quickstart" tabindex="-1">Quickstart <a class="header-anchor" href="#Quickstart" aria-label="Permalink to &quot;Quickstart {#Quickstart}&quot;">​</a></h1><p>From nothing to an agent running code in your Julia REPL, on one Linux machine. For other layouts (a remote backend, Windows, building from source) see <a href="./remote">Going remote</a> and <a href="./install">Install details</a>.</p><p>These docs track <code>main</code>; the installer installs the latest release (<code>--version</code> to pin one).</p><h2 id="Before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#Before-you-start" aria-label="Permalink to &quot;Before you start {#Before-you-start}&quot;">​</a></h2><ul><li><p><strong>Linux x86_64</strong> with <strong>glibc 2.35 or newer</strong> (Ubuntu 22.04 or newer) for the window. Windows and macOS run as frontends to a Linux backend (macOS is experimental). See <a href="/ship-of-tools/dev/start/install#platforms">Platforms</a>.</p></li><li><p>A <strong>desktop session with a display</strong> (X11 or Wayland): the window draws figures, PDFs and typeset math itself, so it needs a graphical desktop, not a terminal. It renders through Vulkan on Linux (Metal on macOS, DirectX 12 or Vulkan on Windows), so the machine needs a working Vulkan driver.</p></li><li><p><strong>git</strong>, <strong>curl</strong> and <strong>tar</strong>.</p></li><li><p><strong>Claude Code</strong> or <strong>Codex</strong>, installed and logged in. The installer does not install either.</p></li><li><p><strong>Julia 1.12</strong> or newer. If Julia is missing, the installer installs it with juliaup; an existing juliaup only gets the 1.12 channel added, so if your default channel is older, run <code>juliaup default 1.12</code> yourself (or set <code>SOT_JULIA_BIN</code>).</p></li><li><p>Optional, on the backend machine: <strong>node/npm</strong> (typeset math in markdown previews renders in a node process; without it math is not typeset), <strong>poppler-utils</strong> (<code>pdftoppm</code> and <code>pdfinfo</code>, for PDF previews) and <strong>ffmpeg</strong> (the poster frame of a video preview).</p></li></ul><div class="warning custom-block"><p class="custom-block-title">Try it in a VM or a separate account</p><p>The installer changes your own agent setup (skills and hooks into your global <code>~/.claude</code> and <code>~/.codex</code>), and there is no isolated mode yet. See <a href="/ship-of-tools/dev/start/install#install-footprint">What the installer changes</a>.</p></div><h2 id="1.-Install" tabindex="-1">1. Install <a class="header-anchor" href="#1.-Install" aria-label="Permalink to &quot;1. Install {#1.-Install}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/kalidke/ship-of-tools/main/scripts/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --local</span></span></code></pre></div><p>Or let an agent do it: start Claude Code or Codex on the machine and say</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Install Ship of Tools: fetch https://raw.githubusercontent.com/kalidke/ship-of-tools/main/docs/INSTALL-AGENT.md and follow it.</span></span></code></pre></div><p>The agent checks the machine, asks where things should run, runs the installer and checks the result.</p><p><code>--local</code> puts the frontend and backend on this machine. The first run instantiates the Julia environments and takes a few minutes. What the installer writes, and how to remove it, is listed under <a href="/ship-of-tools/dev/start/install#install-footprint">What the installer changes</a>.</p><p>For a first try, the release ships a small demo package (waypoints, distances and a CairoMakie route plot). Copy it to your home directory and instantiate it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/share/sot/repo/current/docs/fixtures/DemoProject</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/DemoProject</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">/DemoProject</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.instantiate()&#39;</span></span></code></pre></div><p>The installer does not instantiate the demo package. This step downloads CairoMakie and precompiles it, which takes several minutes the first time.</p><p>The recordings in these docs also show a few files this demo package does not ship — an HDF5 file, a PDF and two figures — generated along the way; do not expect them in a fresh copy.</p><h2 id="2.-Launch" tabindex="-1">2. Launch <a class="header-anchor" href="#2.-Launch" aria-label="Permalink to &quot;2. Launch {#2.-Launch}&quot;">​</a></h2><p>Run <code>sot-launch</code>, or open <strong>Ship of Tools</strong> from your desktop&#39;s application menu. The launcher starts the backend if it is not already running, then opens the window. (With the backend on another machine, the launcher also opens the SSH connection; see <a href="./remote">Going remote</a>.) If no window appears, see <a href="/ship-of-tools/dev/guide/troubleshooting#window-does-not-open">The window does not open</a>.</p><h2 id="3.-What-you-see-on-first-launch" tabindex="-1">3. What you see on first launch <a class="header-anchor" href="#3.-What-you-see-on-first-launch" aria-label="Permalink to &quot;3. What you see on first launch {#3.-What-you-see-on-first-launch}&quot;">​</a></h2><ul><li><p><strong>Files mode</strong> in the left column, rooted at your home directory, with a preview of the file under the cursor in the middle column.</p></li><li><p>An <strong>empty agent pane</strong> on the right, titled <code>llm</code> (with focus, the title shows <code>Agent</code> and that pane&#39;s keys). Nothing runs there until you create a session in the next step.</p></li><li><p>A status line reading <code>connected</code> at the top of the left column.</p></li></ul><p><code>Ctrl+?</code> shows the focused pane&#39;s keys at any time; <code>F1</code> opens the searchable Help drawer.</p><h2 id="start-session" tabindex="-1">4. Start an agent session <a class="header-anchor" href="#start-session" aria-label="Permalink to &quot;4. Start an agent session {#start-session}&quot;">​</a></h2><p>Codex sessions have no REPL skill yet; the REPL steps below are Claude Code only.</p><ol><li><p>Press <strong><code>s</code></strong> for Sessions mode.</p></li><li><p>Move to <strong><code>[+ create new]</code></strong> and press <strong>Enter</strong> to open the directory picker: a folder tree of the backend machine in the navigation pane, starting at your home directory. Move the cursor to your project directory, or to <code>~/DemoProject</code> if you copied the demo package in step 1; <code>Backspace</code> goes up a folder and <code>.</code> shows hidden folders.</p></li><li><p>Press <strong>Enter</strong> for a Claude Code session, <strong>Ctrl+Enter</strong> (Cmd+Enter on macOS) for a Codex session, or <strong>Shift+Enter</strong> for a plain shell with no agent.</p></li></ol><p>The session appears as a row in Sessions mode, and the agent starts in the agent pane with the project directory as its working directory. The first time Claude Code starts in a folder it asks, in the agent pane, whether you trust the files in it; answer there once and the session continues. Each session runs under its own supervisor process on the backend (a <em>capsule</em>), so it keeps running when the window closes.</p><h2 id="5.-Ask-the-agent-to-run-something" tabindex="-1">5. Ask the agent to run something <a class="header-anchor" href="#5.-Ask-the-agent-to-run-something" aria-label="Permalink to &quot;5. Ask the agent to run something {#5.-Ask-the-agent-to-run-something}&quot;">​</a></h2><p>Move focus to the agent pane with <code>Ctrl+Right</code>, twice from the navigation pane (<code>Ctrl+Arrow</code> moves focus between panes), and type a request. In the demo project, for example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>In scripts/route.jl, add a bar chart of the distance of each leg, saved as data/legs.png. Run the script in the REPL and show me the new figure.</span></span></code></pre></div><p>A Claude Code session runs the code in the session&#39;s persistent Julia REPL, the same one you open with <code>Ctrl+J</code>, and every run it makes shows up in that drawer. That REPL starts in the session root&#39;s project — <code>~/DemoProject</code>&#39;s <code>Project.toml</code> here. The drawer is Ship of Tools&#39; own input line, not Julia&#39;s REPL: no <code>?</code> help, no <code>;</code> shell and no Tab completion; use the Terminal drawer or the agent pane for shell commands. When the agent produces a figure it can put the file in your preview pane. Meanwhile its row colour in Sessions mode shows whether it is working, waiting for your answer or done; see <a href="./../concepts/work-state">Work-state colours</a>. See <a href="/ship-of-tools/dev/guide/repl#agents-repl">How agents use the REPL</a>.</p><h2 id="6.-End-a-session,-close-the-window" tabindex="-1">6. End a session, close the window <a class="header-anchor" href="#6.-End-a-session,-close-the-window" aria-label="Permalink to &quot;6. End a session, close the window {#6.-End-a-session,-close-the-window}&quot;">​</a></h2><ul><li><p>In Sessions mode, <code>Shift+D</code> pressed twice on a session&#39;s row ends that session; any other command in between cancels.</p></li><li><p><code>Ctrl+Q</code>, with the navigation pane focused, closes the window. The backend and its sessions keep running; <code>sot-launch</code> opens the window again.</p></li></ul><h2 id="Next" tabindex="-1">Next <a class="header-anchor" href="#Next" aria-label="Permalink to &quot;Next {#Next}&quot;">​</a></h2><ul><li><p><a href="./tour">Your first session</a> — the panes, the agent, the drawers and the modes, one at a time.</p></li><li><p><a href="./../ref/keybindings">Keybindings</a> — every key.</p></li><li><p><a href="./../guide/updating">Updating and rollback</a> — re-running the install command is also the updater.</p></li></ul>`,33)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
